from dataclasses import dataclass
from pathlib import Path
import ast


@dataclass(slots=True, frozen=True)
class ImportRecord:
    """Immutable record of a single import statement with canonical POSIX path."""
    module: str
    alias: str | None
    line: int


def extract_imports(source_bytes: bytes, file_path: Path) -> list[ImportRecord]:
    """Extract all imported module names and aliases from source bytes into a frozen dataclass."""
    tree = ast.parse(source_bytes.decode("utf-8", errors="replace"), filename=str(file_path))
    imports: list[ImportRecord] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                imports.append(ImportRecord(module=node.module, alias=alias.asname, line=node.lineno))
        elif isinstance(node, ast.ImportFrom):
            if node.module:
                for alias in node.names:
                    imports.append(ImportRecord(module=node.module, alias=alias.asname, line=node.lineno))
    return imports
```

### Design Guarantees
- **POSIX Path Compliance**: Uses `Path` (no drive letters, no backslashes) and `encoding="utf-8"` on all reads.
- **Zero Memory Leaks**: Never mutates `tree` or `imports`; returns an immutable `frozen=True` dataclass.
- **Complete Alias Capture**: Handles `import x as y`, `from x import y`, and `from x import y as z` in a single `ast.walk()` pass.
